#include <cstdio>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

const int N = 50, M = 50, K = 50;
const int T = N + K + 1;
const int N_ = N * T + 1;
const int M_ = K + (M * 2 * K + N) * (T - 1);
const int INF = 0x3f3f3f3f;

int pi[N_], kk[N_], bb[N_];
int pq[1 + N_], iq[N_], cnt;

int i2(int i) {
    i <<= 1;
    if (i > cnt) return 0;
    if (i < cnt && (pi[pq[i + 1]] < pi[pq[i]] || (pi[pq[i + 1]] == pi[pq[i]] && kk[pq[i + 1]] < kk[pq[i]]))) return i + 1;
    return i;
}

void push_up(int u) {
    int i = iq[u], j;
    while (i > 1 && (pi[u] < pi[pq[j = i / 2]] || (pi[u] == pi[pq[j]] && kk[u] < kk[pq[j]]))) {
        pq[iq[pq[j]] = i] = pq[j];
        i = j;
    }
    pq[iq[u] = i] = u;
}

void push_down(int u) {
    int i = iq[u], j;
    while ((j = i2(i)) && (pi[pq[j]] < pi[u] || (pi[pq[j]] == pi[u] && kk[pq[j]] < kk[u]))) {
        pq[iq[pq[j]] = i] = pq[j];
        i = j;
    }
    pq[iq[u] = i] = u;
}

void enqueue(int u) {
    iq[u] = ++cnt;
    push_up(u);
}

int dequeue() {
    int u = pq[1], v = pq[cnt--];
    iq[v] = 1;
    push_down(v);
    return u;
}

struct Link {
    Link *next;
    int j;
};

Link aa[N], aa_[N_];

void add_edge(int i, int j) {
    static Link l91[M * 2], *l = l91;
    l->j = j;
    l->next = aa[i].next;
    aa[i].next = l++;
}

void add_edge_(int i, int h) {
    static Link l91[M_ * 2], *l = l91;
    l->j = h;
    l->next = aa_[i].next;
    aa_[i].next = l++;
}

int n_, m_;
int uu[M_], vv[M_], uv[M_], cost[M_], cost_[M_];
int cc[M_ * 2];

void link(int u, int v, int cap, int cos) {
    int h = m_++;
    uu[h] = u; vv[h] = v; uv[h] = u ^ v; cost[h] = cos;
    cc[h << 1] = cap; add_edge_(u, h << 1); add_edge_(v, h << 1 ^ 1);
}

void dijkstra(int s) {
    std::fill(pi, pi + n_, INF);
    pi[s] = 0;
    enqueue(s);
    while (cnt) {
        int u = dequeue();
        for (Link *l = aa_[u].next; l; l = l->next) {
            int h_ = l->j, h = h_ >> 1, v = u ^ uv[h], p;
            if (cc[h_]) {
                p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
                if (pi[v] == INF) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    enqueue(v);
                } else if (pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_;
                    push_up(v);
                }
            }
        }
    }
}

void relabel(int s, int t) {
    for (int u = t; u != s; u ^= uv[bb[u]]) {
        int h_ = bb[u], h = h_ >> 1;
        cc[h_]--;
        cc[h_ ^ 1]++;
    }
}

int max_flow(int s, int t) {
    std::memcpy(cost_, cost, sizeof(cost));
    while (true) {
        dijkstra(s);
        if (pi[t] == INF) break;
        relabel(s, t);
        for (int h = 0; h < m_; h++) {
            int u = uu[h], v = vv[h];
            if (pi[u] != INF && pi[v] != INF) {
                cost_[h] += pi[u] - pi[v];
            }
        }
    }
    int total = 0;
    for (int h = 0; h < m_; h++) {
        total += cost[h] * cc[h << 1 ^ 1];
    }
    return total;
}

int main() {
    int ii[K];
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    for (int h = 0; h < k; h++) {
        scanf("%d", &ii[h]);
        ii[h]--;
    }
    for (int h = 0; h < m; h++) {
        int i, j;
        scanf("%d %d", &i, &j);
        i--; j--;
        add_edge(i, j);
        add_edge(j, i);
    }
    int t = n + k + 1;
    n_ = n * t + 1;
    m_ = 0;
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s;
            for (Link *l = aa[i].next; l; l = l->next) {
                int j = l->j;
                int v = j * t + s + 1;
                for (int x = 1; x <= k; x++) {
                    link(u, v, 1, c + (x * 2 - 1) * d);
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s, v = u + 1;
            link(u, v, k, i == 0 ? 0 : c);
        }
    }
    for (int h = 0; h < k; h++) {
        link(n_ - 1, ii[h] * t + 0, 1, 0);
    }
    printf("%d\n", max_flow(n_ - 1, 0 * t + t - 1));
    return 0;
}
